-- HappiMynd Games Hub: MySQL schema
-- Target: MySQL 8.0+ (InnoDB, utf8mb4). Tested on MySQL 9.4 with time_zone '+00:00'.
--
-- Conventions (same as the current app):
--   * All timestamps are UTC. Run the server/session with time_zone = '+00:00'.
--   * IDs are UUID strings generated by the application (CHAR(36), lowercase).
--   * JSON is stored as text and parsed by the application.
--   * Emoji are stored (avatars, game text), so everything is utf8mb4.

SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- ─────────────────────────────────────────────────────────────────────
-- users: player accounts (shared HappiMynd identity table)
-- In Postgres this table is created outside the hub repo. If another app
-- already owns it in MySQL, keep that table and make sure it has these
-- columns. The hub reads id, name, username, email, avatar, password_hash,
-- created_at.
-- ─────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS users (
  id            CHAR(36)     NOT NULL,                 -- was UUID DEFAULT gen_random_uuid(); now generated by the app
  email         VARCHAR(255) NOT NULL,                 -- stored lowercase by signup
  username      VARCHAR(100) NOT NULL,                 -- stored lowercase by signup
  name          VARCHAR(255) NOT NULL,
  password_hash VARCHAR(255)     NULL,                 -- bcrypt ($2a$/$2b$, 10 rounds)
  avatar        VARCHAR(50)      NULL DEFAULT '🧘',
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  -- utf8mb4_0900_ai_ci is case-insensitive, so these also replace the
  -- Postgres LOWER(email)/LOWER(username) indexes.
  UNIQUE KEY uq_users_email (email),
  UNIQUE KEY uq_users_username (username),
  KEY idx_users_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ─────────────────────────────────────────────────────────────────────
-- sso_tickets: single-use login codes for external games (valid 120 s)
-- Short-lived; existing rows do not need migrating.
-- ─────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS sso_tickets (
  code       CHAR(64)    NOT NULL,                     -- 64 hex chars
  user_id    CHAR(36)    NOT NULL,
  game_id    VARCHAR(50) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  used_at    DATETIME(3)     NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (code),
  KEY idx_sso_user (user_id),
  KEY idx_sso_expires (expires_at),
  CONSTRAINT fk_sso_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ─────────────────────────────────────────────────────────────────────
-- activity_events: hub visits and external game launches (analytics)
-- ─────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS activity_events (
  id         CHAR(36)    NOT NULL,                     -- UUID generated by the server
  event_type VARCHAR(30) NOT NULL,                     -- 'hub_open' | 'external_launch'
  game_slug  VARCHAR(60)     NULL,                     -- only for external_launch
  user_type  VARCHAR(12) NOT NULL,                     -- 'guest' | 'registered'
  user_id    CHAR(36)        NULL,                     -- registered users only; NULL for guests
  created_at DATETIME(3) NOT NULL,                     -- UTC, written by the app
  PRIMARY KEY (id),
  KEY idx_events_type_time (event_type, created_at),
  KEY idx_events_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ─────────────────────────────────────────────────────────────────────
-- game_sessions: one row per play of a built-in game (analytics)
-- ─────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS game_sessions (
  id           CHAR(36)    NOT NULL,                   -- UUID generated in the browser
  game_slug    VARCHAR(60) NOT NULL,
  user_type    VARCHAR(12) NOT NULL,                   -- 'guest' | 'registered'
  user_id      CHAR(36)        NULL,
  started_at   DATETIME(3) NOT NULL,                   -- UTC
  ended_at     DATETIME(3)     NULL,                   -- NULL while the play is open
  duration_sec INT             NULL,                   -- visible-tab seconds, 0..21600
  ended_by     VARCHAR(10)     NULL,                   -- 'done' | 'left'
  stats        TEXT            NULL,                   -- JSON: [{"label": "...", "value": 12}]
  PRIMARY KEY (id),
  KEY idx_sessions_time (started_at),
  KEY idx_sessions_game_time (game_slug, started_at),
  KEY idx_sessions_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ─────────────────────────────────────────────────────────────────────
-- game_overrides: admin edits to a game's library card
-- NULL text column = use the text coded in the app. No row = fully default.
-- ─────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS game_overrides (
  slug        VARCHAR(60)  NOT NULL,
  name        VARCHAR(60)      NULL,                   -- app limit 40
  tagline     VARCHAR(100)     NULL,                   -- app limit 60
  description VARCHAR(300)     NULL,                   -- app limit 160
  hidden      TINYINT(1)   NOT NULL DEFAULT 0,         -- 1 = hidden from the library
  updated_at  DATETIME(3)  NOT NULL,
  PRIMARY KEY (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ─────────────────────────────────────────────────────────────────────
-- game_content: admin-edited in-game text, one row per customised list
-- items = the whole list as a JSON array, in the game's own item shape.
-- No row = the game uses its built-in list.
-- ─────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS game_content (
  game_slug  VARCHAR(60) NOT NULL,
  collection VARCHAR(40) NOT NULL,                     -- e.g. 'thoughts', 'questions', 'end-titles'
  items      MEDIUMTEXT  NOT NULL,                     -- largest list today is ~25 KB
  updated_at DATETIME(3) NOT NULL,
  PRIMARY KEY (game_slug, collection)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
